/**
 * Domain Entity: CreateCategory
 *
 * Validates payload for creating a product category. The `code` is generated by
 * the use case (PC-### scoped per company). The product group is validated by
 * the use case against the company tenant (must exist and be active).
 */
export class CreateCategory {
  public readonly productGroupId: string;
  public readonly name: string;
  public readonly description: string | null;

  constructor(payload: unknown) {
    this._verifyPayload(payload);

    const { productGroupId, name, description } = payload as Record<string, unknown>;

    this.productGroupId = (productGroupId as string).trim();
    this.name = (name as string).trim();
    this.description = description ? (description as string).trim() : null;
  }

  private _verifyPayload(payload: unknown): void {
    if (!payload || typeof payload !== 'object') {
      throw new Error('CREATE_CATEGORY.NOT_CONTAIN_NEEDED_PROPERTY');
    }

    const { productGroupId, name, description } = payload as Record<string, unknown>;

    if (!productGroupId || !name) {
      throw new Error('CREATE_CATEGORY.NOT_CONTAIN_NEEDED_PROPERTY');
    }

    if (typeof productGroupId !== 'string' || typeof name !== 'string') {
      throw new Error('CREATE_CATEGORY.NOT_MEET_DATA_TYPE_SPECIFICATION');
    }
    if (description !== undefined && description !== null && typeof description !== 'string') {
      throw new Error('CREATE_CATEGORY.NOT_MEET_DATA_TYPE_SPECIFICATION');
    }

    if (name.trim().length === 0 || name.trim().length > 100) {
      throw new Error('CREATE_CATEGORY.NAME_LIMIT_CHAR');
    }
    if (description && (description as string).trim().length > 500) {
      throw new Error('CREATE_CATEGORY.DESCRIPTION_LIMIT_CHAR');
    }
  }
}
